inline const GameRuleDef* getGameRuleDefById(uint8_t id) {
    for (size_t i = 0; i < TOTAL_GAME_RULES; i++) {
        if (pgm_read_byte(&(GAME_RULES[i].id)) == id) {
            return &GAME_RULES[i];
        }
    }
    return nullptr;
}

